 # Start well inside the top of the stroke, clear of the eventual outer edges.
 loc=np.array(np.unravel_index(np.argmax(dist),dist.shape))[::-1]
 allp=[loc];cur=loc
 for level in np.arange(margin,dist.max()+.01,spacing):
